<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';$user=requireUser($pdo);
if($_SERVER['REQUEST_METHOD']==='GET'){$q=$pdo->prepare('SELECT id,slug,title,excerpt,status,created_at FROM posts WHERE user_id=? ORDER BY created_at DESC');$q->execute([$user['id']]);exit(json_encode(['user'=>$user,'posts'=>$q->fetchAll()]));}
if($_SERVER['REQUEST_METHOD']==='PUT'){$d=input();$name=trim($d['name']??'');if(strlen($name)<2){http_response_code(422);exit(json_encode(['error'=>'Name is required.']));}$bio=mb_substr(trim($d['bio']??''),0,500);$website=mb_substr(trim($d['website']??''),0,255);$profession=mb_substr(trim($d['profession']??''),0,120);$address=mb_substr(trim($d['address']??''),0,255);$interests=mb_substr(trim($d['interests']??''),0,500);if($website!==''&&!filter_var($website,FILTER_VALIDATE_URL)){http_response_code(422);exit(json_encode(['error'=>'Enter a complete website URL.']));}$q=$pdo->prepare('UPDATE users SET name=?,bio=?,website=?,profession=?,address=?,interests=? WHERE id=?');$q->execute([$name,$bio,$website,$profession,$address,$interests,$user['id']]);exit(json_encode(['ok'=>true]));}
http_response_code(405);echo json_encode(['error'=>'Method not allowed.']);
